create or replace function public.business_manage_location(p_business_id uuid,p_location_id uuid,p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare r locations; role text; begin select lower(bm.role) into role from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() limit 1; if role not in ('owner','admin') and coalesce((select is_admin from profiles where id=auth.uid()),false) is not true then raise exception 'Admin access required'; end if; if p_action='create' then insert into locations(business_id,name,address,city,state,postal_code,country,latitude,longitude,description,phone,website,is_active,is_premium,accessible,changing_table,source,verification_status,created_by) values(p_business_id,coalesce(p_payload->>'name','New Location'),p_payload->>'address',p_payload->>'city',p_payload->>'state',p_payload->>'postal_code',coalesce(p_payload->>'country','US'),nullif(p_payload->>'latitude','')::double precision,nullif(p_payload->>'longitude','')::double precision,p_payload->>'description',p_payload->>'phone',p_payload->>'website',coalesce((p_payload->>'is_active')::boolean,true),coalesce((p_payload->>'is_premium')::boolean,false),coalesce((p_payload->>'accessible')::boolean,false),coalesce((p_payload->>'changing_table')::boolean,false),'business','pending',auth.uid()) returning * into r; elsif p_action='update' then update locations set name=coalesce(p_payload->>'name',name),address=coalesce(p_payload->>'address',address),city=coalesce(p_payload->>'city',city),state=coalesce(p_payload->>'state',state),description=coalesce(p_payload->>'description',description),phone=coalesce(p_payload->>'phone',phone),website=coalesce(p_payload->>'website',website),is_active=coalesce((p_payload->>'is_active')::boolean,is_active),is_premium=coalesce((p_payload->>'is_premium')::boolean,is_premium),updated_at=now() where id=p_location_id and business_id=p_business_id returning * into r; elsif p_action='deactivate' then update locations set is_active=false,updated_at=now() where id=p_location_id and business_id=p_business_id returning * into r; else raise exception 'Unsupported location action'; end if; if r.id is null then raise exception 'Location not found'; end if; return to_jsonb(r); end $$;
create or replace function public.business_manage_qr(p_business_id uuid,p_location_id uuid,p_qr_id uuid,p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare q qr_codes; role text; begin select lower(bm.role) into role from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() limit 1; if role not in ('owner','admin') and coalesce((select is_admin from profiles where id=auth.uid()),false) is not true then raise exception 'Admin access required'; end if; if p_action='create' then insert into qr_codes(location_id,code,active,label,customization) values(p_location_id,encode(gen_random_bytes(12),'hex'),true,coalesce(p_payload->>'label','Location QR'),coalesce(p_payload->'customization','{}'::jsonb)) returning * into q; elsif p_action='update' then update qr_codes set label=coalesce(p_payload->>'label',label),customization=coalesce(p_payload->'customization',customization),active=coalesce((p_payload->>'active')::boolean,active) where id=p_qr_id and location_id=p_location_id returning * into q; elsif p_action='deactivate' then update qr_codes set active=false where id=p_qr_id and location_id=p_location_id returning * into q; else raise exception 'Unsupported QR action'; end if; if q.id is null then raise exception 'QR code not found'; end if; return to_jsonb(q); end $$;
create or replace function public.business_manage_promotion(p_business_id uuid,p_promotion_id uuid,p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare r promotions; role text; begin select lower(bm.role) into role from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() limit 1; if role not in ('owner','admin') and coalesce((select is_admin from profiles where id=auth.uid()),false) is not true then raise exception 'Admin access required'; end if; if p_action='create' then insert into promotions(business_id,location_id,title,description,discount,starts_at,ends_at,active) values(p_business_id,nullif(p_payload->>'location_id','')::uuid,coalesce(p_payload->>'title','New Promotion'),p_payload->>'description',p_payload->>'discount',nullif(p_payload->>'starts_at','')::timestamptz,nullif(p_payload->>'ends_at','')::timestamptz,coalesce((p_payload->>'active')::boolean,true)) returning * into r; elsif p_action='update' then update promotions set title=coalesce(p_payload->>'title',title),description=coalesce(p_payload->>'description',description),discount=coalesce(p_payload->>'discount',discount),starts_at=coalesce(nullif(p_payload->>'starts_at','')::timestamptz,starts_at),ends_at=coalesce(nullif(p_payload->>'ends_at','')::timestamptz,ends_at),active=coalesce((p_payload->>'active')::boolean,active) where id=p_promotion_id and business_id=p_business_id returning * into r; elsif p_action='deactivate' then update promotions set active=false where id=p_promotion_id and business_id=p_business_id returning * into r; else raise exception 'Unsupported promotion action'; end if; if r.id is null then raise exception 'Promotion not found'; end if; return to_jsonb(r); end $$;
create or replace function public.business_manage_event(p_business_id uuid,p_event_id uuid,p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare r business_events; role text; begin select lower(bm.role) into role from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() limit 1; if role not in ('owner','admin') and coalesce((select is_admin from profiles where id=auth.uid()),false) is not true then raise exception 'Admin access required'; end if; if p_action='create' then insert into business_events(business_id,location_id,title,description,event_date,event_time) values(p_business_id,nullif(p_payload->>'location_id','')::uuid,coalesce(p_payload->>'title','New Event'),p_payload->>'description',nullif(p_payload->>'event_date','')::date,nullif(p_payload->>'event_time','')::time) returning * into r; elsif p_action='update' then update business_events set title=coalesce(p_payload->>'title',title),description=coalesce(p_payload->>'description',description),event_date=coalesce(nullif(p_payload->>'event_date','')::date,event_date),event_time=coalesce(nullif(p_payload->>'event_time','')::time,event_time),location_id=coalesce(nullif(p_payload->>'location_id','')::uuid,location_id) where id=p_event_id and business_id=p_business_id returning * into r; else raise exception 'Unsupported event action'; end if; if r.id is null then raise exception 'Event not found'; end if; return to_jsonb(r); end $$;
